(function(global){
'use strict';
const api=global.PoolShedActionAuthority;if(!api||typeof api.registerSourceAdapter!=='function')return;
function arr(v){return Array.isArray(v)?v:[];}function n(v){const x=Number(v);return Number.isFinite(x)?x:0;}function text(v){return String(v==null?'':v);}function lower(v){return text(v).toLowerCase();}
function today(){return new Date().toISOString().slice(0,10);}function ageDays(value){const ms=Date.now()-Date.parse(value||'');return Number.isFinite(ms)?Math.floor(ms/86400000):0;}
function poOutstanding(po){return arr(po.lines).reduce((sum,l)=>sum+Math.max(0,n(l.qty||l.quantity||l.orderedQty)-n(l.receivedQty!=null?l.receivedQty:l.received)),0);}
function purchasing(d){const out=[];arr(d.purchaseOrders).forEach(po=>{const status=lower(po.status),pending=poOutstanding(po);if(!pending||/received|complete|cancel/.test(status))return;const due=text(po.dueDate||po.expectedDate||po.deliveryDate||po.eta).slice(0,10);if(due&&due<today())out.push({dedupeKey:'purchase-order:'+po.id+':delivery-overdue',kind:'exception',category:'purchasing',title:'Supplier delivery overdue',summary:pending+' units remain outstanding from '+text(po.supplier||'supplier')+'.',priority:'high',ownerRole:'Purchasing',dueAt:due+'T17:00:00Z',source:{module:'purchase',type:'purchase_order',id:po.id,route:'#/purchase-orders/'+encodeURIComponent(po.id)},context:{supplierId:text(po.supplierId||po.supplier||'')}});const hasMissingEta=arr(po.lines).some(l=>Math.max(0,n(l.qty||l.quantity)-n(l.receivedQty!=null?l.receivedQty:l.received))>0&&!text(l.eta||l.expectedDate||po.eta||po.expectedDate||po.dueDate));if(hasMissingEta&&ageDays(po.orderedAt||po.createdAt||po.date)>=2)out.push({dedupeKey:'purchase-order:'+po.id+':missing-eta',kind:'follow_up',category:'purchasing',title:'Supplier ETA required',summary:text(po.id)+' has outstanding lines without a confirmed ETA.',priority:'normal',ownerRole:'Purchasing',source:{module:'purchase',type:'purchase_order',id:po.id,route:'#/purchase-orders/'+encodeURIComponent(po.id)},context:{supplierId:text(po.supplierId||po.supplier||'')}});if(/part|short|discrep/.test(status)&&pending>0)out.push({dedupeKey:'purchase-order:'+po.id+':missing-lines',kind:'follow_up',category:'purchasing',title:'Missing PO lines need supplier follow-up',summary:pending+' units are still missing after receipt.',priority:'high',ownerRole:'Purchasing',source:{module:'purchase',type:'purchase_order',id:po.id,route:'#/purchase-orders/'+encodeURIComponent(po.id)}});});return out;}
function sales(d){const out=[];arr(d.salesOrders).forEach(so=>{const status=lower(so.status);if(/cancel|complete|closed/.test(status))return;let uncovered=0;arr(so.lines).forEach(l=>{const qty=n(l.qty||l.quantity),covered=n(l.allocatedQty!=null?l.allocatedQty:l.allocated)+n(l.onPurchaseOrderQty!=null?l.onPurchaseOrderQty:l.onPO)+n(l.transferQty);uncovered+=Math.max(0,qty-covered);});if(uncovered>0)out.push({dedupeKey:'sales-order:'+so.id+':stock-uncovered',kind:'exception',category:'sales',title:'Sales Order stock is not fully covered',summary:uncovered+' units remain uncovered by allocation, transfer or linked PO.',priority:'high',ownerRole:'Sales',source:{module:'salesorders',type:'sales_order',id:so.id,route:'#/sales-orders/'+encodeURIComponent(so.id)},context:{customerId:text(so.customerId||''),projectId:text(so.jobId||'')}});const invoiceState=lower(so.invoiceStatus||so.accountingStatus);if(/shipped|despatched|dispatched/.test(status)&&!['invoiced','invoice sent','paid','authorised','authorized'].includes(invoiceState))out.push({dedupeKey:'sales-order:'+so.id+':billing-review',kind:'review',category:'finance',title:'Shipped Sales Order needs billing review',summary:text(so.id)+' has shipped but is not recorded as invoiced.',priority:'normal',ownerRole:'Accounts',source:{module:'salesorders',type:'sales_order',id:so.id,route:'#/sales-orders/'+encodeURIComponent(so.id)},context:{customerId:text(so.customerId||'')}});});return out;}
function warehouse(d){const out=[];arr(d.stockTakes).forEach(st=>{if(lower(st.status)==='submitted'){const ref=text(st.ref||st.id),variance=arr(st.lines).filter(l=>n(l.countedQty)-n(l.systemQty)!==0).length;out.push({dedupeKey:'stocktake:'+ref+':approval',kind:'review',category:'inventory',title:'Stock take awaiting approval',summary:variance+' variance lines require review.',priority:variance?'high':'normal',ownerRole:'Warehouse',source:{module:'locations',type:'stocktake',id:ref,route:'#/inventory'},context:{locationId:text(st.locationId||'')}});}});arr(d.purchaseReturns).forEach(r=>{if(/awaiting|quarantine|qc|review/.test(lower(r.status)))out.push({dedupeKey:'return:'+text(r.id)+':qc',kind:'exception',category:'warehouse',title:'Return / QC decision required',summary:text(r.id)+' requires a warehouse disposition decision.',priority:'normal',ownerRole:'Warehouse',source:{module:'warehouse',type:'return',id:text(r.id),route:'#/warehouse'}});});return out;}
function projects(d){const out=[];if(!global.PoolShedProjectEngine||typeof global.PoolShedProjectEngine.summary!=='function')return out;arr(d.jobs).forEach(job=>{let s;try{s=global.PoolShedProjectEngine.summary(job,d);}catch(_){s=job._summary;}if(!s)return;const margin=s.margin,profit=Number(s.profit||0),minimum=Number(s.minimumMargin!=null?s.minimumMargin:20),target=Number(s.target!=null?s.target:30);if(profit<0)out.push({dedupeKey:'project:'+job.id+':forecast-loss',kind:'review',category:'project',title:'Project forecasts a loss',summary:text(job.name||job.id)+' is forecasting a loss and requires commercial review.',priority:'critical',ownerRole:'Management',source:{module:'jobs',type:'project',id:job.id,route:'#/projects/'+encodeURIComponent(job.id)},context:{projectId:text(job.id),customerId:text(job.customerId||'')}});else if(margin!=null&&Number(margin)<Math.max(minimum,target))out.push({dedupeKey:'project:'+job.id+':margin-risk',kind:'review',category:'project',title:'Project margin below target',summary:'Forecast margin '+Number(margin).toFixed(1)+'% is below the commercial target.',priority:Number(margin)<minimum?'high':'normal',ownerRole:'Management',source:{module:'jobs',type:'project',id:job.id,route:'#/projects/'+encodeURIComponent(job.id)},context:{projectId:text(job.id),customerId:text(job.customerId||'')}});if(s.invoiceExposure&&s.invoiceExposure.thresholdTriggered)out.push({dedupeKey:'project:'+job.id+':billing-exposure',kind:'review',category:'finance',title:'Project billing review recommended',summary:'Project cost exposure has crossed its billing review threshold.',priority:'normal',ownerRole:'Accounts',source:{module:'jobs',type:'project',id:job.id,route:'#/projects/'+encodeURIComponent(job.id)},context:{projectId:text(job.id)}});});return out;}
function finance(d){const out=[];if(!global.PoolShedFinanceCommand||typeof global.PoolShedFinanceCommand.snapshot!=='function')return out;let snap;try{snap=global.PoolShedFinanceCommand.snapshot();}catch(_){return out;}arr(snap.attention).forEach(x=>{let key='',source={module:'accounting',type:x.type||'finance',id:text(x.sourceId||x.customerId||x.poId||x.orderId||''),route:'#/finance'},title=x.title||'Finance review required',priority=x.severity==='critical'?'critical':'normal';if(x.type==='customer-overdue'){key='finance:customer-overdue:'+x.customerId;source={module:'crm',type:'customer',id:x.customerId,route:'#/customers/'+encodeURIComponent(x.customerId)};}else if(x.type==='three-way'){key='finance:three-way:'+x.poId;source={module:'purchase',type:'purchase_order',id:x.poId,route:'#/purchase-orders/'+encodeURIComponent(x.poId)};}else if(x.type==='invoice-ready'){key='finance:invoice-ready:'+x.orderId;source={module:'salesorders',type:'sales_order',id:x.orderId,route:'#/sales-orders/'+encodeURIComponent(x.orderId)};}else key='finance:'+text(x.type||'review')+':'+text(x.sourceId||x.customerId||x.poId||x.orderId||title);out.push({dedupeKey:key,kind:'review',category:'finance',title,summary:text(x.detail||'£'+Number(x.amount||0).toFixed(2)+' requires review.'),priority,ownerRole:'Accounts',source,context:{customerId:text(x.customerId||''),salesOrderId:text(x.orderId||'')}});});return out;}
function automation(d){const out=[];const c=d.automationCommand||{};arr(c.runs).filter(r=>/failed|error/.test(lower(r.status||r.result))).forEach(r=>out.push({dedupeKey:'automation-run:'+r.id+':failed',kind:'exception',category:'automation',title:'Automation run failed',summary:text(r.result||r.message||'Automation requires manual review.'),priority:'high',ownerRole:'Management',source:{module:'automation',type:'automation_run',id:r.id,route:'#/automation'}}));arr(c.approvals).filter(a=>!['approved','rejected','withdrawn'].includes(lower(a.status))).forEach(a=>out.push({dedupeKey:'automation-approval:'+a.id,kind:'review',category:'automation',title:text(a.name||a.title||'Automation approval required'),summary:'Automation change is waiting for a controlled decision.',priority:'normal',ownerRole:'Management',source:{module:'automation',type:'automation_approval',id:a.id,route:'#/automation'}}));return out;}
const adapters={purchasing,sales,warehouse,projects,finance,automation};Object.keys(adapters).forEach(k=>api.registerSourceAdapter(k,adapters[k]));global.PoolShedActionSourceAdapters=adapters;
})(typeof globalThis!=='undefined'?globalThis:window);
